// Card data types, extracted from the game files by the pipeline.
//
// This module is pure data: no React, no DOM, no browser APIs. It describes the
// shape of a Krosmaga card and the effects it carries.

export type CardType = "Summon" | "Spell" | "Aoe" | "Dofus" | "GameRules";

export type God =
  | "None" | "Iop" | "Cra" | "Eniripsa" | "Ecaflip" | "Enutrof"
  | "Sram" | "Xelor" | "Sacrieur" | "Feca" | "Sadida" | "Rushu";

export type Rarity = "Common" | "Silver" | "Gold" | "Krosmic" | "Infinite";

// AoE scope for stat effects: which creatures they hit.
//   allies, all your creatures, anywhere
//   allies_camp, only your creatures still in your territory ("dans votre camp")
//   enemies, all the foe's creatures
//   all, everyone on the board
export type AoeScope = "allies" | "allies_camp" | "enemies" | "all" | "own_camp" | "enemy_camp";

// Geometric AoE shape around the clicked cell (combines with a scope).
// KROSMAGA VOCABULARY (the board is 5 rows × 10 columns; creatures advance
// horizontally along their row):
//   row    = "ligne", the targeted horizontal lane (same y). There are 5.
//   column = "rangée", the targeted vertical column (same x). There are 10.
//   cross, the targeted row and column; around, the 3×3 block.
export type AoeShape = "row" | "column" | "cross" | "around";

// Effects follow the effect data of the original game.
// Discriminated union on `type` so TS narrows the shape automatically.
export type Effect =
  | { type: "DamageData"; Damage: DynamicValue; pierceArmor?: boolean; targetAttacker?: boolean } // pierceArmor (PERCE ARMURE, Flèche Perçante #294): the spell damage ignores the target's armour (but not its resistance). Set from the description keyword by merge_authored_effects. // targetAttacker (Craqueboule Magmatique #675, on CONTRE_COUP): the damage goes to the creature that just hit the source (routed by fireContreCoup → applyEffectsToAttacker); it applies whether the source survives or not (see the pre-cull capture in processCombatPhase).
  | { type: "DamageDofus"; amount: number; side?: "ally" | "enemy" } // "Infligez N dégât à un de vos dofus pour l'invoquer" (Padgref Démouelle #222): an APPARITION that picks one dofus (side "ally" → ally_dofus) and deals N to it. Kept off the board by the deferred summon: the creature only appears once the dofus is chosen. resolvePendingAction applies the damage (death/win through resolveDeathsAndWin).
  | { type: "DamageAllyToSummon"; amount: number } // "Infligez N dégât à une invocation alliée pour l'invoquer" (Pampactus #218): like DamageDofus but the target is an allied creature (filter ally_creature). A targeted APPARITION kept off the board; the cost (N damage to the chosen ally) is paid at resolution. Cannot be played without another allied creature (CanCastWithNoSecondaryTarget=false).
  | { type: "SacrificeForDamage" } // "Sacrifiez une de vos invocations pour infliger autant de dégâts qu'elle a d'AT à une autre invocation" (Sacrifice #576, Sacrieur): a two-step spell. First pick an allied creature (sacrificed), then another creature (allied or enemy) that takes damage equal to the sacrificed one's AT. The sacrificed creature dies (MORT fires). Cannot be played without an allied creature.
  | { type: "LameEmoussee"; self: number; enemy: number } // "Inflige `self` dégât à une invocation alliée pour infliger `enemy` dégâts à une invocation adverse blessée" (Lame Émoussée #1177, Sacrieur): a two-step spell. First pick an allied creature (takes `self`), then a wounded enemy creature (takes `enemy`). The second target is optional (CanCastWithNoSecondaryTarget): declining only deals `self` to the ally. Cannot be played without an allied creature.
  | { type: "DestroyArmorForDamage"; draw?: number } // "Détruisez l'AR d'une invocation alliée pour infliger autant de dégâts à une autre invocation. Piochez une carte." (Pluie de Météorites #1350, Feca): a two-step spell. First pick an allied creature (its armour is destroyed, set to 0), then another creature (allied or enemy) that takes damage equal to the destroyed armour. The second target is optional (CanCastWithNoSecondaryTarget), but a click is still needed to finish (declining destroys the armour with no damage). `draw` cards are drawn in every case. Cannot be played without an allied creature.
  | { type: "MakeOwnDofusesInvulnerable"; turns: number } // "Confère invulnérable à vos Dofus pour N tour(s)" (Orbe Doré #594, spell with castTarget AlliedGod): sets dofus.invulnerableTurns = turns on every Dofus of the caster; decremented at the start of the caster's turn (1 → it survives the enemy combat phase and ends the next turn). A player-state effect (no pick).
  | { type: "ShieldDofus" } // "Placez un bouclier sur un Dofus allié" (Pissenlit Maléfique #1041): an APPARITION that targets an allied Dofus (ally_dofus) and sets dofus.shielded = true; the shield fully absorbs the first source of damage (woundDofus) and is then used up. Kept off the board by the deferred summon (like MakeDofusInvulnerable).
  | { type: "MakeDofusInvulnerable" } // "ciblez un dofus, il est invulnérable tant que cette invocation est en jeu" (Artheon #1424): an APPARITION that targets any dofus (any_dofus) and sets dofus.invulnerableBy = id of the source. While the source lives, dofusInvulnerable() skips this dofus at every damage/destruction site (combat, AoE, DamageData, DestroyDofus, SetDofusLife). Kept off the board by the deferred summon; the protection ends when the source dies.
  | { type: "DestroyDofus" } // "Détruit un Dofus" (Garde Temps): destroys the Dofus on the targeted cell (spell with castTarget AnyDofus); death/win handled by resolveDeathsAndWin (a real one counts toward the win, a fake one is credited to the destroyer)
  | { type: "AoeDamageDofus"; amount: number } // "Inflige N dégâts à tous les Dofus adverses" (Harcèlement #136): every enemy Dofus loses N life; capture handled by resolveDeathsAndWin
  | { type: "DamageDofusPerArmoredAlly"; amount: number } // "Vos invocations avec de l'AR infligent N au Dofus adverse de leur ligne" (Attaque Naturelle #1012, Feca): a global spell. For each creature of the caster with armour (armor>0), deals N to the enemy Dofus of that creature's row. Several armoured allies on the same row add up on the same Dofus. resolveDeathsAndWin handles the capture.
  | { type: "DamageAllByOwnAttack" } // "Inflige aux invocations en jeu autant de dégâts qu'elles ont d'AT" (Sacrifice Véritable #861, Sacrieur): a global spell. Every living creature (both camps) takes damage equal to its own current AT (armour and resistance apply).
  | { type: "DamageEnemiesByFamilyCount"; family: string; per: number; excludeSelf?: boolean } // "Inflige aux invocations adverses autant de dégâts que de <famille> alliés en jeu" (Tofu Explosif #155 MORT, Tofu family, per 1, excludeSelf): deals (number of allied creatures of `family`, not counting the source) × `per` to every enemy creature.
  | { type: "DamageEnemiesByReserve"; per?: number } // "Inflige aux invocations adverses autant de dégâts que de PA en réserve, puis dépense toute la réserve" (Nox #353 MORT): a state effect. Deals (caster's reserve AP × `per`, default 1) to every enemy creature, then sets the reserve to 0.
  | { type: "DamageEnemiesByEnemyCount"; target: "all" | "ownCamp" | "front"; countZone: "ownCamp" | "board" } // "Inflige aux invocations adverses autant de dégâts que d'invocations adverses [dans votre camp / en jeu]" (Dathura #600/#721/#909, APPARITION, Sram). The amount is the number of enemy creatures in `countZone` (ownCamp = the caster's half / board = the whole board). The target: "all" = every enemy creature (#600); "ownCamp" = enemies in the caster's half (#721); "front" = the first enemy creature in front of the source on its row (#909).
  | { type: "DamageRowByOwnCost" } // "Inflige autant de dégâts que son coût en PA aux AUTRES invocations de sa ligne" (Gargoule #818, HORDE APPARITION): the amount is the AP actually paid to play it (bindata LastAPCost = "cost of the last card played", which is itself on its APPARITION), so printed cost + playedCostMod (HORDE reduction -1 per dead Goule, Polter extra cost...), floored at 0. Hits every other creature (allies and enemies, friendly fire) on the same row (y), except itself.
  | { type: "DamageAdjacentFront"; hitDofus?: boolean } // "Inflige des dégâts équivalents à son AT sur la case devant lui" (Pisti Yeul #932, APPARITION, Sadida): the amount is the source's current AT. Hits whatever is on the single adjacent cell in front (x+forwardDx, same row): a creature (either camp) or, with hitDofus, the Dofus on that cell (the case of the bush placed in front of a Dofus).
  | { type: "DropButinStartRow" } // "MORT : Dépose un Butin allié sur la première case de sa ligne" (Coffres #711/#1320/#1634/#1275): a state effect (MORT). Places a Butin of the caster's camp on the start cell of the source's row (x=8 ally / x=1 enemy); skipped if the cell is taken (same start cell as Dwanlaposh).
  | { type: "TransformKilledToButin" } // "Transforme en Butin allié les invocations qu'il détruit" (Toutancoffron #633): a passive marker (effects[]) read after combat (cdgKills → applyKillToButin). When a creature is destroyed by a living source with this marker, a Butin of the killer's camp is placed on the cell freed by the victim. The victim dies normally (MORT + discard); the Butin is an extra effect. The killer has to survive the exchange (COUP DE GRÂCE convention). One Butin per creature killed; Dofus do not count ("invocations").
  | { type: "SacrificePoupesque"; family?: string; per?: number } // "Sur chaque ligne, inflige à la 1ère invocation ou Dofus adverse des dégâts égaux à 2× le nombre de vos poupées sur la ligne, puis les détruit" (Sacrifice Poupesque #89, Sadida, Doll family, per 2): a global spell. For each row, deals `per`×(caster's dolls on the row) to the enemy creature/Dofus of the row closest to the caster, then destroys all the caster's dolls ("les détruit" means your dolls).
  | { type: "ScatterDamageDofus"; amount: number } // "N dégâts répartis entre les Dofus adverses" (Craps #10): deals N points one by one, each on a living enemy Dofus drawn at random independently (the same one can be hit several times; a captured Dofus leaves the draw; an invulnerable Dofus is excluded). Seeded RNG (reproducible); capture handled by resolveDeathsAndWin.
  | { type: "SetDofusLife"; value: number } // "Faire chuter les PV d'un Dofus à N" (Sanction #151): sets the life of the targeted Dofus (ctx.targetCell, AnyDofus) to value, never raising it (min); capture handled by resolveDeathsAndWin if it reaches 0
  | { type: "SetDiceFloor"; floor: number } // "Durant ce tour vos jets de dé ne peuvent être inférieurs à N" (Dé Pipé #535): sets a floor on the caster's dice rolls until the end of their turn
  | { type: "RevealDofuses"; scope: "all" | "one" | "line"; side?: "ally" | "enemy" } // "Dévoile ... les Dofus": sets `revealed` to true on the matching Dofus. scope `all` (Sang Méprise #211), `one` (the first unrevealed one: Démasqué #1234 / Kerubim l'Aventurier #333 "un dofus adverse"), `line` (those on the source's row via selfCell: Salbatroce #480). `side` (ally/enemy relative to the caster) limits the camp.
  | { type: "DestroyPrismOnRow"; side?: "ally" | "enemy" } // "Détruit le prisme adverse de sa ligne" (Kerubim le Brocanteur #378): removes the prism on the source's row (selfCell.y) that belongs to camp `side` (enemy = not the caster).
  | { type: "DiscardRandomHand"; amount: number } // "Défausse N carte(s) aléatoire(s) de votre main" (Phorzerker #357): moves N random cards from the caster's hand to their discard (drawn with the seeded RNG). Player state.
  | { type: "AttractPrisms"; side?: "ally" | "enemy" } // "Attire tous les prismes adverses vers votre camp" (Attirance #125, Sacrieur): each prism of camp `side` (relative to the caster) slides toward the caster's camp (ally → +x, enemy → −x) as far as it can, stopped by any obstacle (creature, dofus, seed, tas d'os, butin, bush, glyph, another prism). The prism keeps its owner.
  | { type: "RevealEnemyDofusLine"; maxRoll: number } // "Dévoile le Dofus adverse de la ligne sur N ou moins" (Dé du Chateux #459): if the last dice roll (ctx.diceRoll) is at most maxRoll, reveals the enemy Dofus on the target's row
  | { type: "RecoverSelfOnLowRoll"; maxRoll: number } // "Récupérez ce sort sur N ou moins" (Dé Ecaflip #342): a marker read by castSpell. If the spell's dice roll (spellCtx.diceRoll) is at most maxRoll, the spell goes back to the hand instead of the discard
  | { type: "BanishDiscard"; count: number } // "Bannit les N dernières cartes parties dans votre défausse pour ‹effet›" (Sram): a cost marker read by playCard/canPlayCard. Needs at least count cards in the discard (otherwise unplayable) and banishes the `count` most recent ones (to the banished zone, out of the game). The ‹X› effect (damage, summon...) stays a normal effect of the card
  | { type: "BanishAllDiscards" } // "Tant qu'il est en jeu, les cartes défaussées sont bannies à la place" (Nécro Phorreur #1221). A passive marker while in play: as long as a living creature (any camp) has it, resolveDeathsAndWin moves both players' discards into `banished` (the discard stays empty). Not the same as BanishDiscard (an active cost). Affects both players
  | { type: "BoostMovementFromEnemyInLine" } // "Augmente ses PM de la valeur de PM du premier adversaire de sa ligne" (Leanor): scans the row forward (skipping allies), self +PM = baseMovement of the first enemy found
  | { type: "SetPropertyData"; PropertyType: string }
  | { type: "ShooterRangeData"; RangeMin: DynamicValue; RangeMax: DynamicValue }
  | { type: "BoostResistanceData"; Boost: DynamicValue }
  | { type: "CreateCardCounterData"; InitialValue: number; MaxValue: number; Repeatable: boolean; bounceToEnemyHand?: boolean; expireBuffEnemy?: { attack: number; armor: number } }
  | { type: "SinistroData" }
  | { type: "StrikeNextEnemyHardSummon"; damage: number; self: number } // Camille Kaz #785: the next enemy creature hard-cast from hand takes `damage`; Camille then takes `self`. One-shot (per-instance strikeSpent).
  | { type: "ShieldDofusOnRow" } // Championne Endoctrinée #869 APPARITION: shield the caster's Dofus on the SOURCE's row (no pick). Gated by a requireCondition rider (outnumbered).
  | { type: "ShieldAlliedDofuses" } // Maître Féca #1676: give a one-hit shield (shielded) to all of the caster's living Dofus ("… et à vos Dofus").
  | { type: "AddReserveOnKill"; amount: number } // Poussière Temporelle #184: add `amount` to the caster's AP reserve only if the spell's target died ("… si l'invocation meurt"). Mirrors SeedReserveOnKill.
  | { type: "RetreatSelf"; cells: number } // Betty Boubz #145 (CONTRE COUP): the source slides `cells` toward its own wall ("Recule de N cases"), via slideCreatureBack.
  | { type: "PushTargetOnAttack"; distance: number } // Patty Ceriz #31: marker, when this creature attacks (melee or shooter fire), the struck enemy is pushed `distance` cells.
  | { type: "StatPerFamilyInPlay"; stats: ("attack" | "range" | "movement")[]; family: string; per: number; excludeSelf?: boolean } // Eclaireur d'Elite #1182: continuous self-aura, gains `per` of each listed stat per living allied creature of `family` (excludeSelf → "autre").
  | { type: "DamageSameFamilyAsTarget"; amount: number } // Banqueroute #822: deal `amount` to every other creature (both camps) sharing a family with the cast target (the target itself is hit by a sibling DamageData).
  | { type: "DamageEnemiesOnAllyDofusDestroyed"; amount: number } // Héros Martyr #956: while a carrier lives, each time one of its side's Dofus is destroyed, deal `amount` to all enemy creatures.
  | { type: "SacrificeDofusForDamage"; damage: number } // Punition #189: 1st pick = your Dofus (sacrificed/destroyed), 2nd pick = an enemy Dofus that takes `damage`.
  | { type: "AttachSinistro" } // Sinistro #215 (castTarget AlliedDofusWithoutEquipement): attach a Sinistro equipment to the targeted allied Dofus. Replaces the bindata [SinistroData, DamageData{1}, SetPropertyData{EquipementAttached}] so placement deals no damage; the Dofus then fires (FIN_DE_TOUR) and the equipment breaks if the host is wounded (woundDofus).
  | { type: "AttachNecronomigore" } // Nécronomigore #700 (castTarget AlliedDofusWithoutEquipement): attach a Nécronomigore equipment (necronomigoreCounter=6) to the targeted allied Dofus. Replaces the bindata [SetPropertyData{EquipementAttached}, CreateCardCounterData{6}, DamageData{5}] so placement deals no damage; at each owner FIN_DE_TOUR the counter ticks and, once it hits 0 ("au bout de 6 tours"), it deals 5 to all enemy Dofus every turn. Removed when the host Dofus is destroyed (the field lives on the Dofus).
  | { type: "BoostMovementPoisonData"; Value: DynamicValue }
  | { type: "PushData"; Distance: number }
  | { type: "SelfDamageData"; Damage: number }      // synth: "S'inflige N dégâts"
  | { type: "BoostAttackData"; Boost: number }      // synth: "Gagne +N AT" (self)
  | { type: "BoostLifeData"; Boost: number }        // synth: "Gagne +N PV" (self)
  | { type: "HealSelfData"; Heal: number }          // synth: "Se soigne de N PV"
  // --- authored from descriptions (friendly names, `amount` field) ---
  // `scope` (optional) turns a single-target stat effect into an AoE one:
  // "allies" / "enemies" / "all" → applies to a whole side instead of the
  // clicked creature. Stamped by the merge from phrasing like "vos
  // invocations" / "invocations adverses".
  | { type: "Heal"; amount: DynamicValue; scope?: AoeScope; shape?: AoeShape; family?: string; excludeSelf?: boolean; dofus?: boolean }   // "Soigne ... de N PV". dofus=true targets a Dofus (pick any_dofus, Dollie Praan #650 "un Dofus"). The single-target heal can heal the Dofus on the targeted cell (capped at its starting HP), which also covers Mot Reconstituant #491 "une invocation ou un Dofus" through castTarget SummonOrDofus
  | { type: "Destroy" }                             // "Détruit une invocation" (targeted)
  | { type: "SwapBody"; maxAttack?: number }        // "Échange son corps avec une invocation adverse ayant N AT ou moins" (Marline): source and target swap position and camp
  | { type: "DestroyInFront"; maxAttack?: number }  // "Détruit la première créature devant lui si elle possède N AT ou moins" (Gloutoblop)
  | { type: "DamageInFront"; amount: DynamicValue; hitDofus?: boolean; anyCamp?: boolean; bounceKilledToHand?: boolean }  // "Inflige à la première invocation ADVERSE devant lui N dégâts" (Héros Chataîgneur: N = NumberOfSeedsValue): scans the row forward, skips allies, hits the first enemy (any distance). hitDofus (Emma Zone #1866 "invocation OU dofus"): if there is no enemy creature in front, hits the enemy Dofus of its row. anyCamp (Zespadon #564 "la première invocation devant lui", no "adverse"): does not skip allies, so it hits the first creature met, ally or enemy.
  | { type: "DamageDofusOnRow"; amount: number }  // "inflige N dégât au dofus adverse" (Jèms Blond #340, COUP DE GRÂCE): hits the enemy Dofus on the source's row (y) directly ("celui de sa ligne"), without scanning creatures. resolveDeathsAndWin handles the capture.
  | { type: "DamageDofusOnTargetRow"; amount: number }  // "et N au Dofus adverse" (Flèche Criblante #8): the arrow goes through the targeted creature to the enemy Dofus of its row (row y of ctx.targetCell; "adverse" relative to ctx.casterSide, since the spell has no source on the board), "la ligne de l'invocation ciblée". Skips an invulnerable Dofus (Artheon); resolveDeathsAndWin handles the capture.
  | { type: "DamageDofusOnRowOnHeal"; amount: number }  // "inflige N dégât au dofus adverse de sa ligne quand une invocation est soignée" (Malox Makugen #76): passive (like Dargone, not a trigger). applyHealReactions scans each LIFE_HEALED of a creature during an applyEffects and deals N to the enemy Dofus of the row of each living Malox.
  | { type: "DamageDofusOnRowOnEnemyPrismLoss"; amount: number }  // "Inflige N au Dofus adverse de sa ligne quand vous volez OU détruisez un prisme adverse" (Maluss #292): passive (effects[], like Ratchet #589 for Butins). For each enemy prism your camp removes from the board (pickup/steal through activatePrism, or destruction through DestroyPrism/DestroyPrismOnRow/DestroyAllEnemyPrisms), each living Maluss of the camp deals N (× number of prisms lost) to the enemy Dofus of its row (woundDofus).
  | { type: "DamageDofusOnRowOnButinPickup"; amount: number }  // "Inflige N au Dofus adverse de sa ligne quand vous ramassez un Butin" (Ratchet #589): passive (like Malox, not a trigger). applyButinReward (where every Butin pickup by a camp goes through) makes, after the reward, the enemy Dofus of the row of each living Ratchet of the picker take the damage (woundDofus: breaks a Sinistro, skips an invulnerable Dofus; resolveDeathsAndWin handles capture/win).
  | { type: "DamageEnemiesOnAllyHeal"; amount: number }  // "Inflige N dégât(s) aux invocations adverses quand une invocation alliée est soignée" (Pacificatrice Enjouée #1519): passive (like Dargone/Malox, not a trigger). applyHealReactions: for each LIFE_HEALED of an ally of the carrier, deals N to every enemy creature (normal armour/resistance; not the Dofus).
  | { type: "RetaliateAlliesWoundedInCombat"; amount: number } // "Inflige N aux invocations qui blessent vos invocations lors d'un combat" (Rose Maudite #1353): a passive marker (effects[]). While a living carrier exists, every enemy creature that wounds a creature of its camp with a combat attack (melee or ranged, not spells) takes `amount`. Applied in processCombatPhase (scan of the DAMAGE events of the combat phase), once per source per wounded camp.
  | { type: "DamageEnemiesOnAllyDofusDamage"; amount: number } // "Inflige N aux invocations adverses quand un Dofus allié subit des dégâts" (Julith Jurgen #352): a passive marker (effects[]). When a Dofus of the camp of a living carrier takes damage (any source), deals `amount` (fixed, whatever the Dofus took) to every enemy creature. Applied in woundDofus; it only hits creatures (never a Dofus), so no chain is possible. Each living carrier fires once.
  | { type: "MirrorAllyDofusDamageToEnemyRow" } // "Quand un de VOS Dofus subit des dégâts, le Dofus ADVERSE de sa ligne en subit autant" (Sir Comte Flex #406): a passive marker (effects[]). When a Dofus of the camp of a living carrier takes damage (any source: combat, spell, AoE, Sinistro...), the enemy Dofus of the same row (position.y) takes as much. Applied in woundDofus (where all Dofus damage goes through: it breaks a Sinistro, respects dofusInvulnerable, counts for the capture), with an anti-chain guard (isMirror: the mirror does not fire another mirror, so two opposing Flex do not loop). Does nothing if there is no living enemy Dofus on the row.
  | { type: "AoeDestroy"; scope: AoeScope; maxAttack?: number; maxLife?: number; condition?: PlayerCondition; shape?: AoeShape; rarity?: string; property?: string } // "Détruit les invocations ayant N AT/PV ou moins" (mass, filtered; optional condition; shape "around" = 3×3 around the target, e.g. Glyphe de Mort; rarity = only destroys creatures of that rarity, Toxine; property = only those with that property, Razortemps "les invocations inciblables" → Untargetable)
  | { type: "DestroyArmor" }                        // "Détruisez l'AR d'une invocation" (Larve Orange #116): targeted, sets the target's armour to 0
  | { type: "BoostAttack"; amount: DynamicValue; scope?: AoeScope; shape?: AoeShape; family?: string; wounded?: boolean; excludeSelf?: boolean; duration?: "ownNextTurn" | "opponentNextTurn"; requireCondition?: PlayerCondition }   // "Confère +N AT ..." (duration = temporary, e.g. Sénilité; requireCondition = the effect is cancelled if the condition is not met, e.g. "+1 AR si vous avez une Graine en jeu"; wounded = limits the scope to wounded creatures, e.g. Oracle Offensé)
  | { type: "BoostColumnAttack"; amount: DynamicValue; minAttack?: number }   // "Confère +N AT aux invocations d'une rangée" (Tikoko): the player picks a column (vertical, same x); +N AT to both sides on it. amount can be negative (Grokoko #531 "réduit de 1 l'AT"); minAttack = only hits creatures with at least N AT
  | { type: "SpendApAsBuff"; stats: ("attack" | "armor")[] }   // "Dépense vos PA restants pour donner +1 par PA dans chaque stat" (Heure de Gloire): the amount is the AP spent, and all AP is used
  | { type: "SpendApAsDamage" }   // "Dépense vos PA restants pour infliger l'équivalent en dégâts" (Désynchronisation #377): damage to the targeted creature = the caster's remaining AP at cast, then AP goes to 0. Same guard as SpendApAsBuff: unplayable at 0 AP (canPlayCard)
  | { type: "DrainAp"; amount: number }   // "Dépense N PA" with nothing in return (Cactana #587 DÉBUT DU TOUR): removes N from the caster's AP pool, floored at 0 (not SpendApAsBuff, which gives stats, and not "dépense N PA de votre réserve POUR ...")
  | { type: "BoostArmor"; amount: DynamicValue; woundedAmount?: number; scope?: AoeScope; shape?: AoeShape; family?: string; wounded?: boolean; excludeSelf?: boolean; duration?: "ownNextTurn" | "opponentNextTurn"; requireCondition?: PlayerCondition }    // "Confère +N AR ..." (requireCondition = the effect is cancelled if the condition fails; wounded = limits the scope to wounded creatures; woundedAmount = another single-target amount if the chosen target is wounded at resolve, Saizan Zen #522 "+1 AR ou +2 si blessée")
  | { type: "Charge"; cells: number | "toWall" }    // "L'invocation ciblée charge de N cases" (targeted)
  | { type: "ChargeAllies"; cells: number; family?: string; excludeSelf?: boolean; wounded?: boolean } // "Vos (autres) invocations [blessées] chargent de N cases" (scoped charge; wounded = limited to wounded creatures, e.g. La Gerbouille)
  | { type: "ChargeSelf"; cells?: number | DynamicValue }   // "APPARITION : Charge" (Tristepin): the creature charges its own PM right away on summon. cells = moves exactly N cells instead of its whole PM (Lilotte "charge de 1 case quand ..."), or a dice roll (Defhi Croquets #319 "Charge de 1d6 cases", resolved when it fires)
  | { type: "RetreatAllies"; cells: number } // "Vos invocations reculent de N cases" (Tout ou Rien, Face): moves back toward its own wall, with no combat
